const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const modeLabel=mode=>mode==='free'?'Free shop':'Career';
export function saveSummary(state,money){return `<strong>Day ${esc(state.day)} · ${money(state.cash)}</strong><p>${esc(state.playerName)} · ${state.purchases.filter(p=>!p.returned&&!p.delivered).length} kept purchases · ${state.missions.length} completed chapters</p>`;}
export function backupSummary(backup,money){return saveSummary(backup.state,money)+`<small>${backup.savedAt===null?'Backup date unavailable':esc(new Date(backup.savedAt).toLocaleString())}</small>`;}
export function recoveryHTML(slot,money){const changed=slot.reason==='changed',unavailable=slot.status==='unavailable';return `<section class="save-recovery" aria-labelledby="recovery-title"><div class="eyebrow">${modeLabel(slot.mode).toUpperCase()} · SAVE RECOVERY</div><h1 id="recovery-title" tabindex="-1">${unavailable?'Your browser storage is unavailable.':changed?'This save changed in another tab.':'Let’s recover your shopping life.'}</h1><p class="recovery-intro">${unavailable?'Allow storage for this site, then try loading again. Keep this tab open if it holds progress you want to download.':changed?'Saving and gameplay are paused to protect both copies. Download this tab’s progress before loading the other tab’s save.':'Your current save could not be loaded safely. Saving and gameplay are paused. Your stored data stays in place until you confirm a replacement.'}</p>${changed&&slot.state?`<article class="recovery-copy"><h2>Latest stored progress</h2>${saveSummary(slot.state,money)}<button class="button orange" data-action="recovery-retry">Load latest stored progress</button></article>`:''}${unavailable?'<article class="recovery-copy"><h2>Stored progress has not been replaced</h2><p>Backup access is unavailable. Restore storage access and try loading again.</p></article>':slot.backup?`<article class="recovery-copy"><h2>Last-known-good backup</h2>${backupSummary(slot.backup,money)}<button class="button orange" data-action="review-local-backup">Review this recovery</button><button class="button secondary" data-action="download-local-backup">Download backup</button></article>`:`<article class="recovery-copy"><h2>No usable local backup found</h2><p>Import a JSON save you previously downloaded, or start fresh after saving a copy of the stored data.</p></article>`}<div class="recovery-actions">${slot.raw!==null?'<button class="button secondary" data-action="download-damaged">Download stored save data</button>':''}${slot.backupRaw!==null&&!slot.backup?'<button class="button secondary" data-action="download-backup-data">Download unreadable backup data</button>':''}${changed?'<button class="button secondary" data-action="export-save">Download this tab’s progress</button>':''}<button class="button secondary" data-action="import-save">Import a downloaded save</button><button class="button secondary" data-action="recovery-retry">Try loading again</button><button class="text-button" data-action="recovery-other">Open ${slot.mode==='career'?'free shop':'career'} instead</button><button class="text-button" data-action="recovery-new">Start this mode fresh…</button></div><p class="recovery-note">Backups stay in this browser. Clearing site data removes both copies. JSON saves do not include outfit-photo images.</p></section>`;}
